FLAGS_H_BANDS: dict[str, list[str]] = {
    "de": ["#1C1B1F", "#D32F2F", "#FBC02D"],
    "pl": ["#FFFFFF", "#D32F2F"],
    "nl": ["#AE1C28", "#FFFFFF", "#21468B"],
    "ru": ["#FFFFFF", "#0039A6", "#D52B1E"],
    "ua": ["#0057B7", "#FFD700"],
    "gb": ["#012169", "#C8102E", "#012169"],
    "us": ["#B22234", "#FFFFFF", "#3C3B6E"],
    "jp": ["#FFFFFF"],
    "sg": ["#EF3340", "#FFFFFF"],
    "ch": ["#DA291C"],
    "fi": ["#FFFFFF"],
    "se": ["#006AA7"],
    "fr": ["#0055A4", "#FFFFFF", "#EF4135"],
    "ca": ["#FF0000", "#FFFFFF", "#FF0000"],
    "tr": ["#E30A17"],
    "hk": ["#DE2910"],
    "xx": ["#4A4459", "#CAC3DC"],
}


def main() -> None:
    ICONS_DIR.mkdir(parents=True, exist_ok=True)
    FLAGS_DIR.mkdir(parents=True, exist_ok=True)

    for name, body in ICONS.items():
        svg = (
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" '
            'width="24" height="24" fill="#000000">\n'
            f"  {body}\n"
            "</svg>\n"
        )
        (ICONS_DIR / f"{name}.svg").write_text(svg, encoding="utf-8")

    for code, bands in FLAGS_H_BANDS.items():
        if code in {"fr", "ca"}:
            w = 28 / len(bands)
            rects = "".join(
                f'<rect x="{i * w:.2f}" y="0" width="{w:.2f}" height="20" fill="{c}"/>'
                for i, c in enumerate(bands)
            )
        elif code == "jp":
            rects = '<rect width="28" height="20" fill="#FFFFFF"/><circle cx="14" cy="10" r="5" fill="#BC002D"/>'
        elif code == "ch":
            rects = '<rect width="28" height="20" fill="#DA291C"/><rect x="12" y="4" width="4" height="12" fill="#FFFFFF"/><rect x="8" y="8" width="12" height="4" fill="#FFFFFF"/>'
        elif code == "fi":
            rects = '<rect width="28" height="20" fill="#FFFFFF"/><rect x="7" y="0" width="5" height="20" fill="#003580"/><rect x="0" y="7.5" width="28" height="5" fill="#003580"/>'
        elif code == "se":
            rects = '<rect width="28" height="20" fill="#006AA7"/><rect x="7" y="0" width="4" height="20" fill="#FECC00"/><rect x="0" y="8" width="28" height="4" fill="#FECC00"/>'
        else:
            h = 20 / len(bands)
            rects = "".join(
                f'<rect x="0" y="{i * h:.2f}" width="28" height="{h:.2f}" fill="{c}"/>'
                for i, c in enumerate(bands)
            )
        svg = (
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 28 20" width="28" height="20">\n'
            f"  <clipPath id=\"r\"><rect width=\"28\" height=\"20\" rx=\"4\"/></clipPath>\n"
            f"  <g clip-path=\"url(#r)\">{rects}</g>\n"
            "</svg>\n"
        )
        (FLAGS_DIR / f"{code}.svg").write_text(svg, encoding="utf-8")

    print(f"Generated {len(ICONS)} icons and {len(FLAGS_H_BANDS)} flags.")


if __name__ == "__main__":
    main()
